class TFMLogicStepOperatorFindRelatedTable extends TFMLogicBlock implements TFMLogicStepOperatorInterface, TFMLogicBlockProvideTableNamesInterface
{
    TableName                           tableFrom;
    TFMTableRelation                    tableToRelation;
    TableName						    tableTo; 
}

Method.Source:
public Name blockName()
{
    return tableTo ? strFmt("Find %1", tableTo) : "Find Related Table";
}

/// <summary>
/// Provides a set of table names that the current block provides at runtime
/// </summary>
/// <returns>A set of table names as strings</returns>
public Set tablesProvided()
{
    Set tables = new Set(Types::String);
    if (tableTo)
    {
        tables.add(tableTo);
    }
    return tables;
}

[TFMParameter('', "Relation to find Table")]
public TFMTableRelation parmTableToRelation(TFMTableRelation _tableToRelation = tableToRelation)
{
    if (_tableToRelation != tableToRelation)
    {
        tableTo = TFMGenericDataHelper::tableNameFromRelation(_tableToRelation, tableFrom);
    }

    tableToRelation = _tableToRelation;
    return tableToRelation;
}

[TFMParameter('', "Table From")]
public TableName parmTableFrom(TableName _tableFrom = tableFrom)
{
    tableFrom = _tableFrom;
    return tableFrom;
}

public str runLogic ( TFMRequestElement _request )
{
    Common              tableFromBuffer = _request.logicContext().getTableFromAnyBlock(this.parmTableFrom());
    Common              common = TFMGenericDataHelper::tableBufferFromRelation(tableToRelation, tableFromBuffer);

    if (common)
    {
        _request.logicContext().addDataContext(common, this.parmName());
    }
    return '';
}

[TFMLookupMethodForEDT(extendedTypestr(TFMTableRelation))]
public void lookupExpression(FormStringControl _callingControl)
{
    SysDictTable	sdt;
    SysTableLookup                  sysTableLookup  = SysTableLookup::newParameters(tablenum(TmpTableName), _callingControl);
    TmpTableName                    tmpLookup;

    sysTableLookup.addLookupfield(fieldnum(TmpTableName, TableName),true);
    if (!tableFrom)
    {
        return;
    }

    sdt = new SysDictTable(tableName2Id(tableFrom));
    tmpLookup.setTmp();
    SetEnumerator sEnum = sdt.relations().getEnumerator();
    while (sEnum.moveNext())
    {
        SysDictRelation sdr = sEnum.current();

        tmpLookup.TableName  = sdr.name();
        tmpLookup.insert();
    }

    //Find table methods
    sEnum = sdt.methods(true,false,false).getEnumerator();
    while (sEnum.moveNext())
    {
        SysDictMethod sdm = sEnum.current();

        if (sdm.returnType() == Types::Record && sdm.hasImplementation())
        {
            boolean mandatoryParms = false;
            for (int i = 0; i < sdm.parameterCnt(); i++)
            {
                mandatoryParms = mandatoryParms || !sdm.parameterOptional(i + 1);
            }
            if (!mandatoryParms)
            {
                tmpLookup.TableName  = sdm.name() + '()';

                tmpLookup.insert();
            }
        }
    }
    // BP deviation documented
    sysTableLookup.parmTmpBuffer(tmpLookup);
    sysTableLookup.performFormLookup();
}
